import type { CreateHost, Effect, Host, OrderView, Outcome } from '../host.ts';

type Status = OrderView['status'];

interface Order {
  status: Status;
  items: number;
  charges: number;
  refunds: number;
}

const MAX_ITEMS = 3;

const ok = (): Outcome => ({ ok: true });
const refuse = (reason: string): Outcome => ({ ok: false, reason });

const createHost: CreateHost = async () => {
  const orders = new Map<string, Order>();
  const pending = new Map<string, Effect>();
  let nextEffect = 1;

  function request(from: string, kind: string, data: Record<string, unknown>): void {
    const id = `effect-${nextEffect++}`;
    pending.set(id, { id, from, kind, data });
  }

  function withOrder(id: string, act: (o: Order) => Outcome): Outcome {
    const o = orders.get(id);
    if (!o) return refuse(`order ${id} does not exist`);
    return act(o);
  }

  const host: Host = {
    async create(id) {
      if (orders.has(id)) return refuse(`order ${id} already exists`);
      orders.set(id, { status: 'draft', items: 0, charges: 0, refunds: 0 });
      return ok();
    },

    async addItem(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'draft') return refuse(`order is ${o.status}, not a draft`);
        if (o.items >= MAX_ITEMS) return refuse(`a draft holds at most ${MAX_ITEMS} items`);
        o.items++;
        return ok();
      });
    },

    async removeItem(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'draft') return refuse(`order is ${o.status}, not a draft`);
        if (o.items <= 0) return refuse('the draft holds no item');
        o.items--;
        return ok();
      });
    },

    async place(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'draft') return refuse(`order is ${o.status}, not a draft`);
        if (o.items <= 0) return refuse('cannot place an empty order');
        o.status = 'placed';
        o.charges++;
        request(id, 'payment.charge', { amount: o.items });
        return ok();
      });
    },

    async ship(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'paid') return refuse(`order is ${o.status}, not paid`);
        o.status = 'shipped';
        return ok();
      });
    },

    async cancel(id) {
      return withOrder(id, (o) => {
        if (o.status === 'draft') {
          o.status = 'cancelled';
          return ok();
        }
        if (o.status === 'paid') {
          o.status = 'cancelled';
          o.refunds++;
          return ok();
        }
        if (o.status === 'placed') return refuse('payment is in progress');
        return refuse(`order is ${o.status}`);
      });
    },

    async order(id) {
      const o = orders.get(id);
      return o ? { status: o.status, items: o.items, charges: o.charges, refunds: o.refunds } : null;
    },

    async pendingEffects() {
      return [...pending.values()].map((e) => ({ ...e, data: { ...e.data } }));
    },

    async completeEffect(effectId, outcome) {
      const e = pending.get(effectId);
      if (!e) return;
      pending.delete(effectId);
      if (e.kind !== 'payment.charge') return;
      const o = orders.get(e.from);
      if (!o || o.status !== 'placed') return;
      o.status = outcome === 'ok' ? 'paid' : 'failed';
    },
  };

  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('happy path, charge, ship', async () => {
  const h = await createHost();
  assert.deepEqual(await h.addItem('a'), { ok: false, reason: 'order a does not exist' });
  assert.ok((await h.create('a')).ok);
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.ok((await h.addItem('a')).ok);
  assert.equal((await h.addItem('a')).ok, false);
  assert.ok((await h.removeItem('a')).ok);
  assert.ok((await h.place('a')).ok);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ ...e, id: undefined }, { id: undefined, from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.ok((await h.ship('a')).ok);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal(await h.order('zz'), null);
});

test('failed charge, refund on cancel', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.create('b'); await h.addItem('b'); await h.place('b');
  const es = await h.pendingEffects();
  const ea = es.find((e) => e.from === 'a')!;
  const eb = es.find((e) => e.from === 'b')!;
  await h.completeEffect(ea.id, 'failed');
  assert.equal((await h.order('a'))!.status, 'failed');
  assert.equal((await h.cancel('a')).ok, false);
  await h.completeEffect(eb.id, 'ok');
  assert.ok((await h.cancel('b')).ok);
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
});
EOF
